head.script:
scwin.onpageload = function() {
	gen1.insertChild(0);

    //gen1.getChild(0, "ipt1").setNextTabID(gen1.getChild(0, "ipt2"));
	gen1.getChild(0, "ipt1").setNextTabID(gen1.getChild(0, "ipt2").id);
};

	scwin.simulateWrapper = function(target, type, options) {
		WebSquare.wUnit.getJq(target).simulate(type, options);
	}
	scwin.setSimulate1 = function() {
		scwin.simulateWrapper('#gen1_0_ipt2', 'key-sequence', {
			sequence: '123456'
		});
	}
	scwin.checkVal = function() {
		return WebSquare.wUnit.getDomById('gen1_0_ipt3').classList.contains('w2input_focus');
	}	
	scwin.unitTest = function() {
		//Unit
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gen1_0_ipt2').click()");
		WebSquare.wUnit.addCommand("pause", "500");		
		//WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gen1_0_ipt2').focus()");
		WebSquare.wUnit.addCommand("pause", "500");				
		WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
		WebSquare.wUnit.addCommand("pause", "500");

		WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
		WebSquare.wUnit.addCommand("pause", "500");		

		//Run test and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}
	scwin.unitTest();
